plugins {
    id("io.gitlab.arturbosch.detekt")
}

detekt {
    config.setFrom(rootProject.file("config/detekt.yml"))
    buildUponDefaultConfig = true
    parallel = true
}

tasks.withType<io.gitlab.arturbosch.detekt.Detekt>().configureEach {
    jvmTarget = "17"
    reports {
        html.required.set(true)
        sarif.required.set(true)
        txt.required.set(false)
        xml.required.set(false)
    }
}

plugins {
    `java-base`
    idea
}

val sourceSets = the<SourceSetContainer>()

val slopTest by sourceSets.creating {
    compileClasspath += sourceSets["main"].output
    runtimeClasspath += sourceSets["main"].output
}

configurations[slopTest.implementationConfigurationName].extendsFrom(configurations["testImplementation"])
configurations[slopTest.runtimeOnlyConfigurationName].extendsFrom(configurations["testRuntimeOnly"])

dependencies {
    "slopTestImplementation"("com.lemonappdev:konsist:0.17.3")
    "slopTestImplementation"("io.kotest:kotest-runner-junit5:5.9.1")
    "slopTestImplementation"("io.kotest:kotest-assertions-core:5.9.1")
}

idea {
    module {
        testSources.from(slopTest.allSource.sourceDirectories)
        testResources.from(slopTest.resources.sourceDirectories)
    }
}

val slopTask = tasks.register<Test>("slopTest") {
    description = "Run architecture tests — package boundaries, naming, style"
    group = "verification"
    testClassesDirs = slopTest.output.classesDirs
    classpath = slopTest.runtimeClasspath
    useJUnitPlatform()
}

tasks.named("check") {
    dependsOn(slopTask)
}

plugins {
    kotlin("jvm")
    kotlin("plugin.serialization")
}

group = providers.gradleProperty("GROUP").getOrElse("zone.clanker")

kotlin {
    jvmToolchain(17)
    compilerOptions {
        freeCompilerArgs.add("-Xjsr305=strict")
    }
}

tasks.test {
    useJUnitPlatform()
}

import kotlinx.kover.gradle.plugin.dsl.AggregationType
import kotlinx.kover.gradle.plugin.dsl.CoverageUnit

plugins {
    id("org.jetbrains.kotlinx.kover")
}

kover {
    reports {
        filters {
            excludes {
                classes(
                    "*MainKt",
                    "*InstallCommand",
                    "*NukeCommand",
                    "*InitCommand",
                    "*UpdateCommand",
                    "*CompletionCommand",
                    "*StatusCommand",
                    "*ListCommand",
                    "*OnboardingGuide*",
                )
            }
        }
        verify {
            rule {
                minBound(90, CoverageUnit.LINE, AggregationType.COVERED_PERCENTAGE)
            }
        }
    }
}

package zone.clanker.gradle.conventions

import org.gradle.api.Plugin
import org.gradle.api.initialization.Settings
import org.gradle.api.initialization.resolve.RepositoriesMode

class ClkxSettingsPlugin : Plugin<Settings> {
    override fun apply(settings: Settings) {

        settings.pluginManagement {
            repositories {
                mavenCentral()
                gradlePluginPortal()
            }
        }

        @Suppress("UnstableApiUsage")
        settings.dependencyResolutionManagement {
            repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
            repositories {
                mavenCentral()
                gradlePluginPortal()
            }
        }
    }
}

